CREATE TABLE IF NOT EXISTS `customer_accounts` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `account_number` text NOT NULL UNIQUE, `name` text NOT NULL, `credit_limit` real DEFAULT 0 NOT NULL, `balance` real DEFAULT 0 NOT NULL, `payment_terms_days` integer DEFAULT 30 NOT NULL, `status` text DEFAULT 'ACTIVE' NOT NULL);
CREATE TABLE IF NOT EXISTS `customer_purchases` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `account_id` integer NOT NULL, `invoice_number` text NOT NULL UNIQUE, `purchase_date` text NOT NULL, `total` real NOT NULL, `balance` real NOT NULL, `status` text DEFAULT 'OPEN' NOT NULL, FOREIGN KEY (`account_id`) REFERENCES `customer_accounts`(`id`));
CREATE TABLE IF NOT EXISTS `customer_purchase_items` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `purchase_id` integer NOT NULL, `product_name` text NOT NULL, `quantity` real NOT NULL, `unit` text NOT NULL, `unit_price` real NOT NULL, `line_total` real NOT NULL, FOREIGN KEY (`purchase_id`) REFERENCES `customer_purchases`(`id`));
